def reverse_string(s):
    """Return a new string with the characters of s in reverse order."""
    if not isinstance(s, str):
        raise TypeError("reverse_string expects a string, got %s" % type(s).__name__)
    characters = []
    for index in range(len(s) - 1, -1, -1):
        characters.append(s[index])
    return "".join(characters)


def reverse_words(sentence):
    """Reverse the order of whitespace-separated words, keeping each word intact."""
    words = sentence.split()
    reversed_words = []
    for word in reversed(words):
        reversed_words.append(word)
    return " ".join(reversed_words)


def is_palindrome(s, ignore_case=True):
    """Report whether s reads the same forwards and backwards."""
    cleaned = []
    for character in s:
        if character.isalnum():
            cleaned.append(character.lower() if ignore_case else character)
    normalized = "".join(cleaned)
    return normalized == reverse_string(normalized)


def describe(s):
    """Build a one-line report about s and its reversal."""
    reversed_form = reverse_string(s)
    parts = ["%r -> %r" % (s, reversed_form)]
    if is_palindrome(s):
        parts.append("palindrome")
    if " " in s:
        parts.append("words: %r" % reverse_words(s))
    return " | ".join(parts)


def reverse_all(items):
    """Reverse every string in items, skipping values that are not strings."""
    results = []
    for item in items:
        try:
            results.append(reverse_string(item))
        except TypeError:
            continue
    return results


def main():
    samples = ["hello", "Python", "A man, a plan, a canal: Panama", "never odd or even", ""]
    for sample in samples:
        print(describe(sample))

    mixed = ["abc", 42, "level", None, "stressed"]
    print("reversed strings only:", reverse_all(mixed))

    longest = ""
    for sample in samples:
        if len(sample) > len(longest):
            longest = sample
    if longest:
        print("longest sample reversed:", reverse_string(longest))


if __name__ == "__main__":
    main()

