import sys


def validate_mapping(name, value):
    if not isinstance(value, dict):
        raise TypeError("%s must be a dict, got %s" % (name, type(value).__name__))


def update_dict(dict1, dict2):
    validate_mapping("dict1", dict1)
    validate_mapping("dict2", dict2)
    merged_dict = {}
    for key, value in dict1.items():
        merged_dict[key] = value
    for key, value in dict2.items():
        merged_dict[key] = value
    return merged_dict


def classify_keys(dict1, dict2):
    validate_mapping("dict1", dict1)
    validate_mapping("dict2", dict2)
    unchanged, updated, added = [], [], []
    for key in dict2:
        if key not in dict1:
            added.append(key)
        elif dict1[key] != dict2[key]:
            updated.append(key)
    for key in dict1:
        if key not in dict2:
            unchanged.append(key)
    return {"unchanged": sorted(unchanged), "updated": sorted(updated), "added": sorted(added)}


def parse_overrides(args):
    overrides = {}
    for arg in args:
        if "=" not in arg:
            raise ValueError("override %r is not in key=value form" % arg)
        key, raw = arg.split("=", 1)
        key = key.strip()
        if not key:
            raise ValueError("override %r has an empty key" % arg)
        raw = raw.strip()
        try:
            overrides[key] = int(raw)
        except ValueError:
            overrides[key] = raw
    return overrides


