    merged = update_dict(dict1, dict2)
    groups = classify_keys(dict1, dict2)
    lines = []
    for key in sorted(merged):
        if key in groups["added"]:
            lines.append("+ %s = %r" % (key, merged[key]))
        elif key in groups["updated"]:
            lines.append("~ %s = %r (was %r)" % (key, merged[key], dict1[key]))
        else:
            lines.append("  %s = %r" % (key, merged[key]))
    counts = (len(merged), len(groups["added"]), len(groups["updated"]))
    lines.append("total: %d keys (%d added, %d updated)" % counts)
    return lines


