SCHEMES = ('http://', 'https://')


def split_scheme(url):
    """Return (scheme, remainder) for a known scheme, or (None, url)."""
    for scheme in SCHEMES:
        if url.startswith(scheme):
            return scheme, url[len(scheme):]
    return None, url


def host_part(remainder):
    """Return the authority portion of the text following the scheme."""
    for separator in ('/', '?', '#'):
        index = remainder.find(separator)
        if index != -1:
            remainder = remainder[:index]
    return remainder


def valid_host(host):
    """A host needs a dot and non-empty, non-whitespace labels around it."""
    if '.' not in host:
        return False
    labels = host.split('.')
    for label in labels:
        if not label:
            return False
        if label.strip() != label:
            return False
    return True


def is_valid_url(url):
    if not isinstance(url, str):
        return False
    candidate = url.strip()
    if not candidate or any(character.isspace() for character in candidate):
        return False
    scheme, remainder = split_scheme(candidate)
    if scheme is None:
        return False
    return valid_host(host_part(remainder))


def describe(url):
    """Build a one-line verdict explaining why a URL was accepted or not."""
    if is_valid_url(url):
        scheme, remainder = split_scheme(url.strip())
        return '{0!r}: valid ({1} host {2})'.format(
            url, scheme.rstrip(':/'), host_part(remainder))
    scheme, remainder = split_scheme(url.strip() if isinstance(url, str) else '')
    if scheme is None:
        return '{0!r}: invalid (scheme must be http:// or https://)'.format(url)
    return '{0!r}: invalid (bad host {1!r})'.format(url, host_part(remainder))


def main():
    samples = [
        'https://www.example.com',
        'ftp://invalid-url',
        'http://example.org/path?q=1',
        'http://nodot',
        'https://.com',
        '  https://spaced.example.com  ',
        'https://exa mple.com',
    ]
    accepted = 0
    for sample in samples:
        print(describe(sample))
        if is_valid_url(sample):
            accepted += 1
    print('{0} of {1} samples accepted'.format(accepted, len(samples)))


if __name__ == '__main__':
    main()

