def cubes_up_to(limit):
    """Return the cubes of every integer from 0 to limit inclusive."""
    if not isinstance(limit, int) or isinstance(limit, bool):
        raise TypeError("limit must be an int, got {!r}".format(limit))
    if limit < 0:
        raise ValueError("limit must be non-negative, got {}".format(limit))
    cubes_list = [n ** 3 for n in range(limit + 1)]
    return cubes_list


def sum_of_cubes(limit):
    """Sum the cubes up to limit, which equals the square of the n-th triangular number."""
    return sum(cubes_up_to(limit))


def perfect_cubes_in(values):
    """Select the values that are cubes of a non-negative integer."""
    selected = []
    for value in values:
        root = round(abs(value) ** (1.0 / 3.0)) if value else 0
        if root ** 3 == value:
            selected.append(value)
    return selected


def format_table(limit, width=6):
    """Build an aligned 'n -> n**3' table for the cubes up to limit."""
    lines = []
    for n, cube in enumerate(cubes_up_to(limit)):
        lines.append("{:>{w}} -> {:>{w}}".format(n, cube, w=width))
    return "\n".join(lines)


def parse_limit(text):
    """Convert a command-line style argument into a usable limit."""
    stripped = text.strip()
    if not stripped:
        raise ValueError("no limit given")
    if not stripped.isdigit():
        raise ValueError("limit must be a non-negative integer, got {!r}".format(text))
    return int(stripped)


def report(limit):
    """Print the cube table, the running total and a cube check for one limit."""
    print("cubes up to {}: {}".format(limit, cubes_up_to(limit)))
    print(format_table(limit))
    total = sum_of_cubes(limit)
    triangular = limit * (limit + 1) // 2
    print("sum of cubes = {}".format(total))
    if total == triangular ** 2:
        print("matches triangular({})^2 = {}".format(limit, triangular ** 2))
    else:
        print("identity broken for limit {}".format(limit))


def main(argv):
    if len(argv) > 1:
        limits = []
        for arg in argv[1:]:
            try:
                limits.append(parse_limit(arg))
            except ValueError as exc:
                print("skipping {!r}: {}".format(arg, exc))
    else:
        limits = [3, 0]
    for limit in limits:
        report(limit)
        print("-" * 20)
    candidates = [1, 5, 8, 27, 30, 64, 100, 125]
    print("cubes among {}: {}".format(candidates, perfect_cubes_in(candidates)))


if __name__ == "__main__":
    import sys

    main(sys.argv)

