def calculate_stock_profit(buy_price, sell_price, quantity):
    """Return the total profit (positive) or loss (negative) for one trade."""
    validate_trade(buy_price, sell_price, quantity)
    return (float(sell_price) - float(buy_price)) * quantity


def validate_trade(buy_price, sell_price, quantity):
    """Raise ValueError/TypeError if the trade parameters are not usable."""
    for name, price in (("buy_price", buy_price), ("sell_price", sell_price)):
        if isinstance(price, bool) or not isinstance(price, (int, float)):
            raise TypeError("{0} must be a number".format(name))
        if price < 0:
            raise ValueError("{0} must not be negative".format(name))
    if isinstance(quantity, bool) or not isinstance(quantity, int):
        raise TypeError("quantity must be an integer")
    if quantity <= 0:
        raise ValueError("quantity must be positive")


def return_percentage(buy_price, sell_price):
    """Percentage return per share, or None when the buy price is zero."""
    if buy_price == 0:
        return None
    return (sell_price - buy_price) / buy_price * 100.0


def format_money(amount):
    """Format a signed amount with two decimals and a currency symbol."""
    if amount < 0:
        return "-${0:,.2f}".format(abs(amount))
    return "${0:,.2f}".format(amount)


def describe_trade(symbol, buy_price, sell_price, quantity):
    """Build a one-line human readable summary of a trade."""
    profit_loss = calculate_stock_profit(buy_price, sell_price, quantity)
    if profit_loss > 0:
        verdict = "PROFIT"
    elif profit_loss < 0:
        verdict = "LOSS"
    else:
        verdict = "BREAK-EVEN"
    percentage = return_percentage(buy_price, sell_price)
    if percentage is None:
        percentage_text = "n/a"
    else:
        percentage_text = "{0:+.2f}%".format(percentage)
    return "{0:<6}{1:>4} @ {2:>9} -> {3:>9}  {4:>11}  {5:>8}  {6}".format(
        symbol,
        quantity,
        format_money(buy_price),
        format_money(sell_price),
        format_money(profit_loss),
        percentage_text,
        verdict,
    )


def portfolio_report(trades):
    """Print a line per trade and return the net profit/loss of all trades."""
    net = 0.0
    for symbol, buy_price, sell_price, quantity in trades:
        print(describe_trade(symbol, buy_price, sell_price, quantity))
        net += calculate_stock_profit(buy_price, sell_price, quantity)
    return net


def main():
    trades = [
        ("AAPL", 10.0, 12.0, 100),
        ("MSFT", 15.0, 13.0, 50),
        ("TSLA", 240.5, 240.5, 20),
        ("NVDA", 98.25, 121.4, 35),
    ]
    net = portfolio_report(trades)
    print("-" * 72)
    print("Net result: {0}".format(format_money(net)))
    if net < 0:
        print("The portfolio is down overall.")


if __name__ == "__main__":
    main()

