def _split_segments(query_string):
    """Split a raw query string into non-empty 'key=value' segments."""
    text = query_string.strip()
    if text.startswith('?'):
        text = text[1:]
    fragment = text.find('#')
    if fragment != -1:
        text = text[:fragment]
    segments = []
    for piece in text.split('&'):
        if piece:
            segments.append(piece)
    return segments


def parse_url_params(query_string):
    """Parse a URL query string into a dictionary of key-value pairs."""
    if not isinstance(query_string, str):
        raise TypeError('query_string must be a str')
    params = {}
    for segment in _split_segments(query_string):
        if '=' in segment:
            key, value = segment.split('=', 1)
        else:
            key, value = segment, ''
        key = key.strip()
        if key:
            params[key] = value
    return params


def collect_duplicates(query_string):
    """Return keys that appear more than once, with all of their values."""
    seen = {}
    for segment in _split_segments(query_string):
        key = segment.split('=', 1)[0].strip()
        if not key:
            continue
        value = segment.split('=', 1)[1] if '=' in segment else ''
        seen.setdefault(key, []).append(value)
    duplicates = {}
    for key, values in seen.items():
        if len(values) > 1:
            duplicates[key] = values
    return duplicates


def format_params(params):
    """Build a human-readable, stable listing of parsed parameters."""
    if not params:
        return '  (no parameters)'
    width = max(len(key) for key in params)
    lines = []
    for key in sorted(params):
        value = params[key]
        shown = value if value else '<empty>'
        lines.append('  {0:<{1}} -> {2}'.format(key, width, shown))
    return '\n'.join(lines)


def main():
    samples = [
        'name=John&age=30',
        'q=python+programming',
        '?sort=asc&sort=desc&page=2&debug#anchor',
        '',
    ]
    for sample in samples:
        print('query: {0!r}'.format(sample))
        params = parse_url_params(sample)
        print(format_params(params))
        duplicates = collect_duplicates(sample)
        for key, values in sorted(duplicates.items()):
            print('  note: {0} repeated {1} times: {2}'.format(
                key, len(values), ', '.join(values)))
        print()


if __name__ == '__main__':
