def longest_common_prefix(strings):
    if not strings:
        return ""

    min_len = float('inf')
    for s in strings:
        if len(s) < min_len:
            min_len = len(s)

    prefix = ""
    for i in range(min_len):
        char = strings[0][i]
        all_match = True
        for j in range(1, len(strings)):
