import sys
from collections import Counter


def count_words_in_file(filepath):
    """Return the total number of whitespace-separated words in a text file."""
    total = 0
    with open(filepath, encoding="utf-8") as handle:
        for line in handle:
            total += len(line.split())
    return total


def count_words_per_line(filepath):
    """Return a list with the word count of each line of the file."""
    counts = []
    with open(filepath, encoding="utf-8") as handle:
        for line in handle:
            counts.append(len(line.split()))
    return counts


def word_frequencies(filepath):
    """Return a Counter of normalised words (lower-cased, stripped of punctuation)."""
    frequencies = Counter()
    with open(filepath, encoding="utf-8") as handle:
        for line in handle:
            for raw in line.split():
                word = raw.strip(".,;:!?\"'()[]").lower()
                if word:
                    frequencies[word] += 1
    return frequencies


def format_report(filepath, top=3):
    """Build a multi-line summary of the word statistics of one file."""
    total = count_words_in_file(filepath)
    per_line = count_words_per_line(filepath)
    frequencies = word_frequencies(filepath)
    lines = [
        "file: {}".format(filepath),
        "total words: {}".format(total),
        "lines: {}".format(len(per_line)),
    ]
    if per_line:
        longest = max(per_line)
        average = total / len(per_line)
        lines.append("longest line: {} words".format(longest))
        lines.append("average per line: {:.2f} words".format(average))
    for word, count in frequencies.most_common(top):
        lines.append("  {:<12} {}".format(word, count))
    return "\n".join(lines)


def main(argv):
    paths = argv[1:]
    if not paths:
        paths = ["test.txt"]
    grand_total = 0
    for path in paths:
        try:
            print(format_report(path))
        except OSError as error:
            print("cannot read {}: {}".format(path, error), file=sys.stderr)
        else:
            grand_total += count_words_in_file(path)
    if len(paths) > 1:
        print("grand total: {} words".format(grand_total))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

