def generate_permutations(lst):
    """Return a list containing every ordering of the elements in lst."""
    if not isinstance(lst, (list, tuple)):
        raise TypeError("generate_permutations expects a list")
    items = list(lst)
    if len(items) <= 1:
        return [items]
    result = []
    for index, element in enumerate(items):
        rest = items[:index] + items[index + 1:]
        for tail in generate_permutations(rest):
            result.append([element] + tail)
    return result


def unique_permutations(lst):
    """Return permutations with duplicates removed, keeping first-seen order."""
    seen = set()
    unique = []
    for permutation in generate_permutations(lst):
        key = tuple(repr(item) for item in permutation)
        if key not in seen:
            seen.add(key)
            unique.append(permutation)
    return unique


def format_permutations(permutations, separator=" "):
    """Render each permutation as a line of separator-joined string parts."""
    lines = []
    for permutation in permutations:
        parts = []
        for item in permutation:
            parts.append(str(item))
        lines.append(separator.join(parts))
    return lines


def report(lst):
    """Build a human readable report about the permutations of lst."""
    all_perms = generate_permutations(lst)
    distinct = unique_permutations(lst)
    header = "Input {0} -> {1} permutations".format(lst, len(all_perms))
    if len(distinct) != len(all_perms):
        header += " ({0} distinct)".format(len(distinct))
    lines = [header]
    for line in format_permutations(distinct, separator=", "):
        lines.append("    [" + line + "]")
    return "\n".join(lines)


def main():
    samples = [
        [1, 2],
        ['a'],
        [],
        ['x', 'y', 'z'],
        [1, 1, 2],
    ]
    for sample in samples:
        print(report(sample))


if __name__ == "__main__":
    main()

