def simple_hash(s):
    """Return the sum of the ASCII (code point) values of all characters in s."""
    if not isinstance(s, str):
        raise TypeError("simple_hash expects a string")
    total = 0
    for ch in s:
        total += ord(ch)
    return total


def hash_all(words):
    """Map each word to its simple hash, preserving input order."""
    results = []
    for word in words:
        results.append((word, simple_hash(word)))
    return results


def group_by_hash(words):
    """Group words that share the same simple hash value."""
    groups = {}
    for word, value in hash_all(words):
        if value not in groups:
            groups[value] = []
        groups[value].append(word)
    return groups


def find_collisions(words):
    """Return the hash values shared by two or more distinct words."""
    collisions = {}
    for value, members in group_by_hash(words).items():
        distinct = sorted(set(members))
        if len(distinct) > 1:
            collisions[value] = distinct
    return collisions


def bucket_index(s, buckets):
    """Place s in one of `buckets` slots using its simple hash."""
    if buckets < 1:
        raise ValueError("buckets must be at least 1")
    return simple_hash(s) % buckets


def bucket_table(words, buckets):
    """Distribute words across a fixed number of buckets."""
    table = [[] for _ in range(buckets)]
    for word in words:
        table[bucket_index(word, buckets)].append(word)
    return table


def format_report(words, buckets):
    """Build a human-readable report of hashes, buckets and collisions."""
    lines = ["hash values:"]
    for word, value in hash_all(words):
        label = repr(word) if word == "" else word
        lines.append("  {:<10} -> {}".format(label, value))
    lines.append("buckets ({}):".format(buckets))
    for index, members in enumerate(bucket_table(words, buckets)):
        if members:
            lines.append("  [{}] {}".format(index, ", ".join(members)))
        else:
            lines.append("  [{}] (empty)".format(index))
    collisions = find_collisions(words)
    if collisions:
        lines.append("collisions:")
        for value in sorted(collisions):
            lines.append("  {} <- {}".format(value, " ".join(collisions[value])))
    else:
        lines.append("collisions: none")
    return "\n".join(lines)


def main():
    words = ["cat", "act", "tac", "dog", "god", "bird", ""]
    print(format_report(words, 5))


if __name__ == "__main__":
    main()

