def is_sorted(values):
    """Return True when every element is not greater than the one after it."""
    for index in range(len(values) - 1):
        if values[index] > values[index + 1]:
            return False
    return True


def validate_input(values, name):
    """Check that values is a sequence of numbers in non-decreasing order."""
    if not isinstance(values, (list, tuple)):
        raise TypeError("{0} must be a list or tuple".format(name))
    for item in values:
        if isinstance(item, bool) or not isinstance(item, (int, float)):
            raise TypeError("{0} must contain only numbers".format(name))
    if not is_sorted(values):
        raise ValueError("{0} must already be sorted".format(name))
    return list(values)


def merge_sorted_lists(list1, list2):
    """Merge two sorted lists of numbers into one new sorted list."""
    left = validate_input(list1, "list1")
    right = validate_input(list2, "list2")
    merged = []
    i = 0
    j = 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            merged.append(left[i])
            i += 1
        else:
            merged.append(right[j])
            j += 1
    while i < len(left):
        merged.append(left[i])
        i += 1
    while j < len(right):
        merged.append(right[j])
        j += 1
    return merged


def merge_many(lists):
    """Merge any number of sorted lists by repeated pairwise merging."""
    result = []
    for current in lists:
        result = merge_sorted_lists(result, current)
    return result


def format_merge(list1, list2):
    """Build a human readable report line for one merge operation."""
    try:
        merged = merge_sorted_lists(list1, list2)
    except (TypeError, ValueError) as error:
        return "{0!r} + {1!r} -> error: {2}".format(list1, list2, error)
    return "{0!r} + {1!r} -> {2!r}".format(list1, list2, merged)


def main():
    cases = [
        ([1, 3, 5], [2, 4, 6]),
        ([10], []),
        ([], []),
        ([-4, -1, 0], [-2, 7]),
        ([1.5, 2.5], [1, 2, 3]),
        ([3, 1], [2]),
        ([1, 2], "34"),
    ]
    for first, second in cases:
        print(format_merge(first, second))
    groups = [[1, 9], [2, 3], [], [0, 4, 11]]
    print("merged groups -> {0!r}".format(merge_many(groups)))


if __name__ == "__main__":
    main()

