def calculate_factorial(n):
  """Return n! for a non-negative integer n, computed iteratively."""
  if not isinstance(n, int) or isinstance(n, bool):
    raise TypeError("n must be an integer, got {!r}".format(n))
  if n < 0:
    raise ValueError("n must be non-negative, got {}".format(n))
  result = 1
  for factor in range(2, n + 1):
    result *= factor
  return result


def binomial(n, k):
  """Return the number of ways to choose k items from n, using factorials."""
  if k < 0 or k > n:
    return 0
  numerator = calculate_factorial(n)
  denominator = calculate_factorial(k) * calculate_factorial(n - k)
  return numerator // denominator


def digit_sum(value):
  """Return the sum of the decimal digits of a non-negative integer."""
  total = 0
  while value > 0:
    total += value % 10
    value //= 10
  return total


def trailing_zeros(value):
  """Return how many zeros the decimal form of value ends with."""
  count = 0
  while value % 10 == 0 and value > 0:
    count += 1
    value //= 10
  return count


def abbreviate(value, limit=20):
  """Return the decimal form of value, shortened if it is very long."""
  text = str(value)
  if len(text) > limit:
    head = text[:limit - 8]
    tail = text[-5:]
    return "{}...{} ({} digits)".format(head, tail, len(text))
  return text


def factorial_report(numbers):
  """Build one report line per requested n, describing its factorial."""
  lines = []
  for n in numbers:
    try:
      value = calculate_factorial(n)
    except (TypeError, ValueError) as error:
      lines.append("{!r:>6} : error: {}".format(n, error))
      continue
    lines.append("{:>6} : {:<34} digit sum {:>4}, trailing zeros {:>3}".format(
      n, abbreviate(value), digit_sum(value), trailing_zeros(value)))
  return lines


def main():
  for line in factorial_report([0, 1, 5, 10, 20, 50, -3, 2.5]):
    print(line)
  print()
  deck, hand = 52, 5
  print("Five-card hands from a 52-card deck: {}".format(binomial(deck, hand)))
  for k in range(0, 6):
