def find_divisors(n):
    """Return all positive divisors of n in ascending order."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 1:
        raise ValueError("n must be a positive integer")
    small = []
    large = []
    step = 1
    while step * step <= n:
        if n % step == 0:
            small.append(step)
            partner = n // step
            if partner != step:
                large.append(partner)
        step += 1
    large.reverse()
    return small + large


def proper_divisors(n):
    """Return the divisors of n excluding n itself."""
    divisors = find_divisors(n)
    return divisors[:-1]


def classify(n):
    """Label n as perfect, abundant or deficient from its proper divisors."""
    total = sum(proper_divisors(n))
    if total == n:
        return "perfect"
    if total > n:
        return "abundant"
    return "deficient"


def is_prime(n):
    """A number is prime when it has exactly two divisors."""
    return len(find_divisors(n)) == 2


def divisor_pairs(n):
    """Return the (a, b) pairs with a * b == n and a <= b."""
    pairs = []
    for divisor in find_divisors(n):
        partner = n // divisor
        if divisor <= partner:
            pairs.append((divisor, partner))
    return pairs


def format_report(n):
    """Build a one-line human readable summary for n."""
    divisors = find_divisors(n)
    listing = ", ".join(str(d) for d in divisors)
    pairs = " ".join("{0}x{1}".format(a, b) for a, b in divisor_pairs(n))
    kind = classify(n)
    if is_prime(n):
        kind += ", prime"
    return "{0:>4}: [{1}] ({2}) pairs: {3}".format(n, listing, kind, pairs)


def main():
    samples = [1, 7, 12, 28, 36, 97, 100, 496]
    for number in samples:
        print(format_report(number))
    perfects = []
    for candidate in range(2, 1001):
        if classify(candidate) == "perfect":
            perfects.append(candidate)
    print("perfect numbers up to 1000:", perfects)
    most = max(range(1, 101), key=lambda k: len(find_divisors(k)))
    print("most divisors below 101:", most, find_divisors(most))


if __name__ == "__main__":
    main()

