def calculate_percentage(part, whole):
    """Return part as a percentage of whole, or None if whole is zero."""
    if not isinstance(part, (int, float)) or isinstance(part, bool):
        raise TypeError("part must be a number, got {!r}".format(part))
    if not isinstance(whole, (int, float)) or isinstance(whole, bool):
        raise TypeError("whole must be a number, got {!r}".format(whole))
    if whole == 0:
        return None
    return float(part) / float(whole) * 100.0


def format_percentage(value, decimals=2):
    """Render a percentage value (or None) as a display string."""
    if value is None:
        return "n/a"
    return "{0:.{1}f}%".format(value, decimals)


def parse_pair(text):
    """Parse a 'part/whole' line into two floats."""
    fields = text.replace("/", " ").split()
    if len(fields) != 2:
        raise ValueError("expected two numbers in {!r}".format(text))
    numbers = []
    for field in fields:
        numbers.append(float(field))
    return numbers[0], numbers[1]


def percentage_table(pairs, decimals=2):
    """Build report rows of (part, whole, formatted percentage)."""
    rows = []
    for part, whole in pairs:
        value = calculate_percentage(part, whole)
        rows.append((part, whole, format_percentage(value, decimals)))
    return rows


def render_table(rows):
    """Turn report rows into aligned text lines."""
    header = ("part", "whole", "percentage")
    cells = [header]
    for part, whole, shown in rows:
        cells.append(("{:g}".format(part), "{:g}".format(whole), shown))
    widths = []
    for column in range(3):
        widest = 0
        for row in cells:
            if len(row[column]) > widest:
                widest = len(row[column])
        widths.append(widest)
    lines = []
    for row in cells:
        parts = []
        for column in range(3):
            parts.append(row[column].rjust(widths[column]))
        lines.append("  ".join(parts))
    return lines


def main():
    raw_inputs = ["50 / 200", "10 / 0", "1 3", "7.5 / 12.5", "0 / 100"]
    pairs = []
    for raw in raw_inputs:
        try:
            pairs.append(parse_pair(raw))
        except ValueError as error:
            print("skipping input: {}".format(error))
    for line in render_table(percentage_table(pairs)):
        print(line)
    undefined = 0
    for part, whole in pairs:
        if calculate_percentage(part, whole) is None:
            undefined += 1
    print("{} of {} ratios were undefined".format(undefined, len(pairs)))


if __name__ == "__main__":
    main()

