    """Build report lines for one generated password per requested length."""
    lines = []
    for length in lengths:
        password = generate_password(length)
        counts = composition(password)
        parts = []
        for name in CATEGORIES:
            parts.append("%s=%d" % (name, counts[name]))
        lines.append(ROW % (password, strength(password), " ".join(parts)))
    return lines


def main():
    print(ROW % ("PASSWORD", "RATING", "COMPOSITION"))
    for line in report([4, 8, 12, 16]):
        print(line)


if __name__ == "__main__":
