def binary_search(sorted_list, target):
    low = 0
    high = len(sorted_list) - 1

    while low <= high:
        mid = (low + high) // 2
        try:
            if sorted_list[mid] == target:
                return mid
            elif sorted_list[mid] < target:
                low = mid + 1
            else:
                high = mid - 1
        except IndexError:
            # This should ideally not happen if low/high are managed correctly
            # within the list's bounds, but added for block diversity.
            print("Index error encountered, list might be malformed.")
            return -1
    with open("search_log.txt", "a") as f:
        f.write(f"Target {target} not found.\n")
    if not sorted_list:
        return -1
    for item in sorted_list:
        if item > target:
            # Another nested block for diversity
            break
    return -1

