def is_valid_isbn10(isbn):
    if not isinstance(isbn, str):
        return False
    if len(isbn) != 10:
        return False

    checksum_sum = 0
    for i in range(9):
        char = isbn[i]
        if not '0' <= char <= '9':
            return False
        checksum_sum += int(char) * (i + 1)

    last_char = isbn[9]
    if '0' <= last_char <= '9':
        checksum_sum += int(last_char) * 10
    elif last_char == 'X':
        checksum_sum += 10 * 10
    else:
        return False

    if checksum_sum % 11 == 0:
        return True
    else:
        return False

