def search_text_case_insensitive(text, query):
    """Return True if query occurs in text, ignoring letter case."""
    if not isinstance(text, str) or not isinstance(query, str):
        raise TypeError("both text and query must be strings")
    return query.casefold() in text.casefold()


def find_all_positions(text, query):
    """Return every start index where query occurs in text, case-insensitively."""
    if not query:
        return []
    haystack = text.casefold()
    needle = query.casefold()
    positions = []
    start = haystack.find(needle)
    while start != -1:
        positions.append(start)
        start = haystack.find(needle, start + 1)
    return positions


def matching_lines(text, query):
    """Return (line number, line) pairs for lines containing query."""
    results = []
    for number, line in enumerate(text.splitlines(), start=1):
        if search_text_case_insensitive(line, query):
            results.append((number, line))
    return results


def highlight(text, query):
    """Wrap each case-insensitive match in text with square brackets."""
    positions = find_all_positions(text, query)
    if not positions:
        return text
    pieces = []
    cursor = 0
    width = len(query)
    for start in positions:
        if start < cursor:
            continue
        pieces.append(text[cursor:start])
        pieces.append("[" + text[start:start + width] + "]")
        cursor = start + width
    pieces.append(text[cursor:])
    return "".join(pieces)


def format_report(text, query):
    """Build a human readable summary of searching text for query."""
    lines = ["query: %r" % query]
    if not search_text_case_insensitive(text, query):
        lines.append("  no match")
        return "\n".join(lines)
    for number, line in matching_lines(text, query):
        lines.append("  line %d: %s" % (number, highlight(line, query)))
    return "\n".join(lines)


def main():
    document = (
        "Hello World\n"
        "Python powers many WORLDS\n"
        "the world keeps turning\n"
        "java is elsewhere\n"
    )
    for query in ("world", "java", "PYTHON", "cobol"):
        print(format_report(document, query))


if __name__ == "__main__":
    main()

