import math


def calculate_sample_std_dev(numbers):
    """Return the sample standard deviation of a list of numbers."""
    values = validate_numbers(numbers)
    count = len(values)
    if count < 2:
        return 0.0
    mean = sum(values) / count
    total_squared_deviation = 0.0
    for value in values:
        deviation = value - mean
        total_squared_deviation += deviation * deviation
    return math.sqrt(total_squared_deviation / (count - 1))


def validate_numbers(numbers):
    """Coerce an iterable of numeric values into a list of floats."""
    if isinstance(numbers, (str, bytes)):
        raise TypeError("expected a list of numbers, got a string")
    values = []
    for index, item in enumerate(numbers):
        if isinstance(item, bool) or not isinstance(item, (int, float)):
            raise TypeError("element %d is not a number: %r" % (index, item))
        if math.isnan(item) or math.isinf(item):
            raise ValueError("element %d is not finite: %r" % (index, item))
        values.append(float(item))
    return values


def parse_series(text):
    """Parse a whitespace or comma separated series of numbers."""
    tokens = text.replace(",", " ").split()
    numbers = []
    for token in tokens:
        numbers.append(float(token))
