def strip_scheme(url):
    """Remove a leading protocol specifier such as 'http://' from the URL."""
    separator = "://"
    position = url.find(separator)
    if position != -1:
        return url[position + len(separator):]
    return url


def extract_host(url):
    """Return the host portion of a URL, without credentials, port or path."""
    remainder = strip_scheme(url.strip())
    for delimiter in ("/", "?", "#"):
        cut = remainder.find(delimiter)
        if cut != -1:
            remainder = remainder[:cut]
    if "@" in remainder:
        remainder = remainder.rsplit("@", 1)[1]
    if ":" in remainder:
        remainder = remainder.split(":", 1)[0]
    return remainder.lower()


def extract_domain(url):
    """Extract the main domain name, without 'www.' and without the TLD."""
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    host = extract_host(url)
    if not host:
        raise ValueError("no host found in URL: %r" % url)
    labels = [label for label in host.split(".") if label]
    if labels and labels[0] == "www":
        labels = labels[1:]
    if len(labels) > 1:
        labels = labels[:-1]
    if not labels:
        raise ValueError("no domain found in URL: %r" % url)
    return labels[-1]


def describe(url):
    """Build a one-line description of the domain extracted from a URL."""
    try:
        domain = extract_domain(url)
    except (TypeError, ValueError) as error:
        return "%-40s -> error: %s" % (url, error)
    return "%-40s -> %s" % (url, domain)


def summarize(urls):
    """Count how many URLs map to each domain, preserving first-seen order."""
    counts = {}
    order = []
    for url in urls:
        try:
            domain = extract_domain(url)
        except (TypeError, ValueError):
            continue
        if domain not in counts:
            counts[domain] = 0
            order.append(domain)
        counts[domain] += 1
    return [(domain, counts[domain]) for domain in order]


def main():
    urls = [
        "http://www.google.com/search",
        "https://blog.openai.org/post",
        "https://user:pass@shop.example.co.uk:8443/cart?id=7",
        "ftp://files.google.com/pub",
        "localhost:5000/health",
        "https:///broken",
    ]
    for url in urls:
        print(describe(url))
    print("-" * 52)
    for domain, count in summarize(urls):
        label = "hit" if count == 1 else "hits"
        print("%-12s %d %s" % (domain, count, label))


if __name__ == "__main__":
    main()

