import sys


def get_quadrant(x, y):
    """Return the quadrant (1-4) containing (x, y), or 0 if it lies on an axis."""
    if x == 0 or y == 0:
        return 0
    if x > 0:
        if y > 0:
            return 1
        return 4
    if y > 0:
        return 2
    return 3


def parse_point(text):
    """Parse a 'x y' or 'x,y' pair into a tuple of floats."""
    fields = text.replace(",", " ").split()
    if len(fields) != 2:
        raise ValueError("expected two coordinates, got %d" % len(fields))
    values = []
    for field in fields:
        try:
            values.append(float(field))
        except ValueError:
            raise ValueError("not a number: %r" % field)
    return values[0], values[1]


def format_coordinate(value):
    """Render a coordinate without a trailing '.0' for whole numbers."""
    if value == int(value):
        return str(int(value))
    return repr(value)


def describe(x, y):
    """Build a one-line report for a single point."""
    quadrant = get_quadrant(x, y)
    label = "(%s, %s)" % (format_coordinate(x), format_coordinate(y))
    if quadrant == 0:
        if x == 0 and y == 0:
            return "%s -> 0 (origin)" % label
        if y == 0:
            return "%s -> 0 (on the x-axis)" % label
        return "%s -> 0 (on the y-axis)" % label
    return "%s -> quadrant %d" % (label, quadrant)


def read_lines(argv):
    """Yield the input lines, from arguments if present, otherwise stdin."""
    if argv:
        for argument in argv:
            yield argument
    else:
        for line in sys.stdin:
            stripped = line.strip()
            if stripped:
                yield stripped


def main(argv):
    status = 0
    for raw in read_lines(argv):
        try:
            x, y = parse_point(raw)
        except ValueError as error:
            print("skipping %r: %s" % (raw, error), file=sys.stderr)
            status = 1
            continue
        print(describe(x, y))
    return status


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

