import sys


def is_valid_passport_number(number):
    """Return True if number is a string of exactly 9 digits."""
    if not isinstance(number, str):
        return False
    if len(number) != 9:
        return False
    for char in number:
        if char not in "0123456789":
            return False
    return True


def normalize(raw):
    """Strip surrounding blanks and internal separators used on forms."""
    cleaned = raw.strip()
    for separator in (" ", "-", "."):
        cleaned = cleaned.replace(separator, "")
    return cleaned


def describe(raw):
    """Return a human readable verdict for a single raw entry."""
    cleaned = normalize(raw)
    if is_valid_passport_number(cleaned):
        return cleaned, "valid"
    if cleaned == "":
        return cleaned, "rejected: empty entry"
    digits = [char for char in cleaned if char.isdigit()]
    if len(digits) != len(cleaned):
        return cleaned, "rejected: contains non-digit characters"
    if len(cleaned) < 9:
        return cleaned, "rejected: too short (%d digits)" % len(cleaned)
    return cleaned, "rejected: too long (%d digits)" % len(cleaned)


def read_entries(argv):
    """Take entries from the command line, falling back to standard input."""
    if len(argv) > 1:
        return argv[1:]
    entries = []
    for line in sys.stdin:
        stripped = line.strip()
        if stripped:
            entries.append(stripped)
    return entries


def report(entries):
    """Print one verdict per entry and return the number of valid ones."""
    valid_count = 0
    for raw in entries:
        cleaned, verdict = describe(raw)
        if verdict == "valid":
            valid_count += 1
        shown = cleaned if cleaned else "<blank>"
        print("%-12s %s" % (shown, verdict))
    return valid_count


def main(argv):
    entries = read_entries(argv)
    if not entries:
        print("no passport numbers supplied")
        return 1
    valid_count = report(entries)
    print("%d of %d entries are valid passport numbers" % (valid_count, len(entries)))
    if valid_count != len(entries):
        return 2
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

