def parse_log_line(log_line: str) -> dict:
  log_components = {}
  try:
    parts = log_line.split(': ', 2)
    if len(parts) >= 2:
      time_level_part = parts[0]
      if len(parts) == 3:
        log_components['message'] = parts[2]
      elif len(parts) == 2:
        # Handle cases where message might be empty or missing
        log_components['message'] = ""

      # Split timestamp and level
      space_index = time_level_part.rfind(' ')
      if space_index != -1:
        potential_level_part = time_level_part[space_index + 1:]
        if len(potential_level_part) <= 8 and potential_level_part.isupper():  # Heuristic for level
          log_components['level'] = potential_level_part
          log_components['timestamp'] = time_level_part[:space_index]
        else:
          # Fallback if the last word isn't a clear level
          log_components['timestamp'] = time_level_part
          log_components['level'] = "UNKNOWN"
      else:
