def calculate_median(numbers):
    """Return the median of a list of numbers without modifying the input."""
    if not numbers:
        return None
    ordered = sorted(numbers)
    count = len(ordered)
    middle = count // 2
    if count % 2 == 1:
        return ordered[middle]
    return (ordered[middle - 1] + ordered[middle]) / 2


def calculate_quartiles(numbers):
    """Return (Q1, Q2, Q3) using the median of the lower and upper halves."""
    if not numbers:
        return (None, None, None)
    ordered = sorted(numbers)
    middle = len(ordered) // 2
    lower = ordered[:middle]
    if len(ordered) % 2 == 1:
        upper = ordered[middle + 1:]
    else:
        upper = ordered[middle:]
    return (calculate_median(lower), calculate_median(ordered), calculate_median(upper))


def parse_numbers(text):
    """Convert a whitespace/comma separated string into a list of numbers."""
    values = []
    for token in text.replace(",", " ").split():
        try:
            number = float(token)
        except ValueError:
            raise ValueError("not a number: {!r}".format(token))
        if number.is_integer():
            number = int(number)
        values.append(number)
    return values


def format_number(value):
    if value is None:
        return "n/a"
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)


def describe(numbers):
    """Build a human readable one-line summary of a data set."""
    q1, q2, q3 = calculate_quartiles(numbers)
    parts = ["n={}".format(len(numbers)), "median={}".format(format_number(q2))]
    if q1 is not None:
        parts.append("Q1={}".format(format_number(q1)))
        parts.append("Q3={}".format(format_number(q3)))
    return ", ".join(parts)


def main():
    samples = ["1 3 2", "1, 4, 2, 3", "", "7", "10 2 38 23 38 23 21"]
    for raw in samples:
        numbers = parse_numbers(raw)
        snapshot = list(numbers)
        summary = describe(numbers)
        if numbers != snapshot:
            raise AssertionError("input list was modified")
        print("{:<24} -> {}".format(repr(raw), summary))


if __name__ == "__main__":
    main()

