def has_unmet_dependencies(task_name, tasks, completed_tasks):
    task_info = None
    for task in tasks:
        if task['name'] == task_name:
            task_info = task
            break

    if task_info is None:
        return True # Task not found, considered to have unmet dependencies

    for dependency in task_info['dependencies']:
        is_completed = False
        for completed_task in completed_tasks:
            if completed_task == dependency:
                is_completed = True
                break
        if not is_completed:
            return True

    return False

