def filter_dict_by_keys(original_dict, keys_to_keep):
    """Return a new dict with only the pairs whose key appears in keys_to_keep."""
    if not isinstance(original_dict, dict):
        raise TypeError("original_dict must be a dict")
    if isinstance(keys_to_keep, (str, bytes)) or not hasattr(keys_to_keep, "__iter__"):
        raise TypeError("keys_to_keep must be a list of strings")
    wanted = set(keys_to_keep)
    filtered = {}
    for key, value in original_dict.items():
        if key in wanted:
            filtered[key] = value
    return filtered


def missing_keys(original_dict, keys_to_keep):
    """List the requested keys that are absent from original_dict, order preserved."""
    absent = []
    for key in keys_to_keep:
        if key not in original_dict and key not in absent:
            absent.append(key)
    return absent


def format_dict(mapping):
    """Render a mapping as a stable, readable one-line string."""
    parts = []
    for key in mapping:
        parts.append("{}={!r}".format(key, mapping[key]))
    return "{" + ", ".join(parts) + "}"


def describe_filtering(original_dict, keys_to_keep):
    """Build a multi-line report about one filtering operation."""
    result = filter_dict_by_keys(original_dict, keys_to_keep)
    absent = missing_keys(original_dict, keys_to_keep)
    lines = [
        "input   : " + format_dict(original_dict),
        "keep    : " + ", ".join(str(key) for key in keys_to_keep),
        "result  : " + format_dict(result),
    ]
    if absent:
        lines.append("warning : no such key(s): " + ", ".join(absent))
    dropped = len(original_dict) - len(result)
    if dropped:
        lines.append("dropped : {} pair(s)".format(dropped))
    return "\n".join(lines)


def main():
    cases = [
        ({'a': 1, 'b': 2, 'c': 3}, ['a', 'c']),
        ({'name': 'Alice', 'age': 30, 'city': 'NY'}, ['name', 'city']),
        ({'x': 10}, ['x', 'y']),
        ({}, ['anything']),
    ]
    for original_dict, keys_to_keep in cases:
        print(describe_filtering(original_dict, keys_to_keep))
        print("-" * 40)

    bad_inputs = [(['a', 'b'], ['a']), ({'a': 1}, 'a')]
    for original_dict, keys_to_keep in bad_inputs:
        try:
            filter_dict_by_keys(original_dict, keys_to_keep)
        except TypeError as error:
            print("rejected: {}".format(error))


if __name__ == "__main__":
    main()

