def count_substring_occurrences_ci(main_string, sub_string):
    """Count occurrences of sub_string in main_string, ignoring case."""
    validate_inputs(main_string, sub_string)
    return len(find_occurrence_positions(main_string, sub_string))


def validate_inputs(main_string, sub_string):
    """Reject arguments that cannot be searched meaningfully."""
    for name, value in (("main_string", main_string), ("sub_string", sub_string)):
        if not isinstance(value, str):
            raise TypeError("{0} must be a str, got {1}".format(name, type(value).__name__))
    if sub_string == "":
        raise ValueError("sub_string must not be empty")


def find_occurrence_positions(main_string, sub_string):
    """Return the start indices of every case-insensitive match (overlaps included)."""
    haystack = main_string.casefold()
    needle = sub_string.casefold()
    positions = []
    start = 0
    while True:
        index = haystack.find(needle, start)
        if index < 0:
            break
        positions.append(index)
        start = index + 1
    return positions


def highlight_matches(main_string, sub_string, marker="[]"):
    """Return main_string with each match wrapped in the given marker pair."""
    if len(marker) != 2:
        raise ValueError("marker must consist of exactly two characters")
    span = len(sub_string)
    pieces = []
    cursor = 0
    for index in find_occurrence_positions(main_string, sub_string):
        if index < cursor:
            continue
        pieces.append(main_string[cursor:index])
        pieces.append(marker[0] + main_string[index:index + span] + marker[1])
        cursor = index + span
    pieces.append(main_string[cursor:])
    return "".join(pieces)


def format_report(main_string, sub_string):
    """Build a one-line human readable summary of the search."""
    count = count_substring_occurrences_ci(main_string, sub_string)
    if count == 0:
        return "'{0}' does not appear in {1!r}".format(sub_string, main_string)
    plural = "time" if count == 1 else "times"
    return "'{0}' appears {1} {2}: {3}".format(
        sub_string, count, plural, highlight_matches(main_string, sub_string)
    )


def main():
    samples = [
        ("Hello world, World wide web", "world"),
        ("Python is Fun", "fun"),
        ("abababa", "ABA"),
        ("Nothing to see here", "xyz"),
    ]
    for main_string, sub_string in samples:
        print(format_report(main_string, sub_string))
    try:
        count_substring_occurrences_ci("some text", "")
    except ValueError as error:
        print("rejected:", error)


if __name__ == "__main__":
    main()

