def validate_sequence(numbers):
    """Check that the input really is a permutation of 1..N+1 with one gap."""
    if not isinstance(numbers, list):
        raise TypeError("expected a list of integers")
    limit = len(numbers) + 1
    seen = set()
    for value in numbers:
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("all elements must be integers: got %r" % (value,))
        if value < 1 or value > limit:
            raise ValueError("value %d outside the range 1..%d" % (value, limit))
        if value in seen:
            raise ValueError("duplicate value %d" % value)
        seen.add(value)
    return limit


def find_missing_element(numbers):
    """Return the single missing number from a permutation of 1..len(numbers)+1."""
    limit = validate_sequence(numbers)
    expected = limit * (limit + 1) // 2
    actual = 0
    for value in numbers:
        actual += value
    return expected - actual


def insertion_index(numbers, missing):
    """Index in the sorted sequence where the missing value belongs."""
    position = 0
    for value in sorted(numbers):
        if value > missing:
            break
        position += 1
    return position


def describe(numbers):
    """Build a one-line report about the gap in the given sequence."""
    try:
        missing = find_missing_element(numbers)
    except (TypeError, ValueError) as error:
        return "%r -> invalid input (%s)" % (numbers, error)
    return "%r -> missing %d (belongs at index %d)" % (
        numbers,
        missing,
        insertion_index(numbers, missing),
    )


