import math


def validate_vector(vec, name):
    if not isinstance(vec, (tuple, list)):
        raise TypeError(name + " must be a tuple of two numbers")
    if len(vec) != 2:
        raise ValueError(name + " must contain exactly two components")
    for component in vec:
        if isinstance(component, bool) or not isinstance(component, (int, float)):
            raise TypeError(name + " components must be numbers")
    return tuple(vec)


def calculate_dot_product(vec1, vec2):
    x1, y1 = validate_vector(vec1, "vec1")
    x2, y2 = validate_vector(vec2, "vec2")
    return x1 * x2 + y1 * y2


def magnitude(vec):
    x, y = validate_vector(vec, "vec")
    return math.sqrt(x * x + y * y)


def angle_between(vec1, vec2):
    denominator = magnitude(vec1) * magnitude(vec2)
    if denominator == 0:
        return None
    cosine = calculate_dot_product(vec1, vec2) / denominator
    if cosine > 1.0:
        cosine = 1.0
    elif cosine < -1.0:
        cosine = -1.0
    return math.degrees(math.acos(cosine))


def classify_relation(vec1, vec2):
    product = calculate_dot_product(vec1, vec2)
    if product == 0:
        if magnitude(vec1) == 0 or magnitude(vec2) == 0:
            return "undefined (zero vector)"
        return "perpendicular"
    if product > 0:
        return "acute angle"
    return "obtuse angle"


def format_vector(vec):
    parts = []
    for component in vec:
        if isinstance(component, int):
            parts.append(str(component))
        else:
            parts.append("{0:.3g}".format(component))
    return "(" + ", ".join(parts) + ")"


def describe_pair(vec1, vec2):
    product = calculate_dot_product(vec1, vec2)
    line = "{0} . {1} = {2}".format(format_vector(vec1), format_vector(vec2), product)
    theta = angle_between(vec1, vec2)
    if theta is None:
        return line + "  [" + classify_relation(vec1, vec2) + "]"
    return line + "  [{0}, {1:.2f} deg]".format(classify_relation(vec1, vec2), theta)


def main():
    pairs = [
        ((1, 2), (3, 4)),
        ((0, 5), (10, 0)),
        ((-1, -1), (2, 3)),
        ((1.5, -2.5), (4, 0.5)),
        ((0, 0), (7, 8)),
    ]
    for vec1, vec2 in pairs:
        print(describe_pair(vec1, vec2))


if __name__ == "__main__":
    main()

