def parse_url_params(url_string):
    if '?' not in url_string:
        return {}

    try:
        query_string = url_string.split('?', 1)[1]
        params = {}
        if query_string:
            for pair in query_string.split('&'):
                if '=' in pair:
                    key, value = pair.split('=', 1)
                    params[key] = value
                else:
                    # Handle keys without values (e.g., "?key&key2=value")
                    params[pair] = ''
            return params
        else:
            return {}
    except IndexError:
        # This catch block is for cases where '?' is at the end, e.g. "http://example.com?"
        # The split might result in an empty second element, which is handled gracefully.
        return {}

