def remove_duplicates_unordered(items):
    """Return a new list containing each distinct element of `items` once.

    Hashable elements are deduplicated with a set; elements that cannot be
    hashed (lists, dicts, ...) fall back to equality comparison.
    """
    seen = set()
    unhashable = []
    unique = []
    for item in items:
        try:
            if item not in seen:
                seen.add(item)
                unique.append(item)
        except TypeError:
            if item not in unhashable:
                unhashable.append(item)
                unique.append(item)
    return unique


def duplicate_counts(items):
    """Map the repeated elements of `items` to how often they occur."""
    counts = {}
    for item in items:
        key = repr(item)
        if key in counts:
            counts[key] += 1
        else:
            counts[key] = 1
    return {key: n for key, n in counts.items() if n > 1}


def format_report(items):
    """Build a short multi-line summary of the deduplication of `items`."""
    unique = remove_duplicates_unordered(items)
    removed = len(items) - len(unique)
    lines = ["input:  {}".format(items), "unique: {}".format(unique)]
    if removed:
        lines.append("removed {} duplicate element(s)".format(removed))
        for key, n in sorted(duplicate_counts(items).items()):
            lines.append("  {} appeared {} times".format(key, n))
    else:
        lines.append("no duplicates found")
    return "\n".join(lines)


def main():
    samples = [
        [1, 2, 2, 3, 1, 4],
        ['a', 'b', 'a', 'c'],
        [],
        [[1, 2], [1, 2], [3], 'x', 'x'],
    ]
    for sample in samples:
        print(format_report(sample))
        print("-" * 40)


if __name__ == "__main__":
    main()

