def calculate_average(numbers):
    """Return the arithmetic mean of numbers, or 0.0 for an empty list."""
    if not numbers:
        return 0.0
    total = 0.0
    for value in numbers:
        total += value
    return total / len(numbers)


def parse_numbers(text):
    """Turn a comma or whitespace separated string into a list of floats."""
    cleaned = text.replace(",", " ")
    values = []
    for token in cleaned.split():
        try:
            values.append(float(token))
        except ValueError:
            raise ValueError("not a number: {!r}".format(token))
    return values


def spread(numbers):
    """Return (minimum, maximum) of numbers, or (0.0, 0.0) when empty."""
    if not numbers:
        return 0.0, 0.0
    low = high = float(numbers[0])
    for value in numbers[1:]:
        if value < low:
            low = float(value)
        if value > high:
            high = float(value)
    return low, high


def above_average(numbers):
    """Return the values that are strictly greater than the mean."""
    mean = calculate_average(numbers)
    return [value for value in numbers if value > mean]


def format_report(label, numbers):
    """Build a short multi-line summary for one data set."""
    mean = calculate_average(numbers)
    low, high = spread(numbers)
    lines = ["{}: {} value(s)".format(label, len(numbers))]
    lines.append("  mean  = {:.2f}".format(mean))
    if numbers:
        lines.append("  range = {:.2f} .. {:.2f}".format(low, high))
        outliers = above_average(numbers)
        if outliers:
            lines.append("  above mean: " + ", ".join("{:g}".format(v) for v in outliers))
        else:
            lines.append("  above mean: none")
    else:
        lines.append("  range = (no data)")
    return "\n".join(lines)


def main():
    datasets = [
        ("first", "1, 2, 3, 4, 5"),
        ("second", "10 20"),
        ("empty", ""),
        ("broken", "3, x, 9"),
    ]
    for label, raw in datasets:
        try:
            numbers = parse_numbers(raw)
        except ValueError as exc:
            print("{}: skipped ({})".format(label, exc))
            continue
        print(format_report(label, numbers))


if __name__ == "__main__":
    main()

