def calculate_future_value_simple(principal, rate, years):
    if not isinstance(principal, (int, float)):
        raise TypeError("Principal must be a number.")
    if not isinstance(rate, (int, float)):
        raise TypeError("Rate must be a number.")
    if not isinstance(years, int):
        raise TypeError("Years must be an integer.")

    if principal < 0:
        raise ValueError("Principal cannot be negative.")
    if rate < 0:
        raise ValueError("Rate cannot be negative.")
    if years < 0:
        raise ValueError("Years cannot be negative.")

    future_value = principal
    for _ in range(years):
        interest_for_year = principal * rate
        future_value += interest_for_year
        if future_value < 0: # Check for overflow (highly unlikely for simple interest)
            print("Warning: Future value became negative, potential overflow or invalid input.")

    if years == 0:
        return principal
    else:
        return float(future_value)

