def validate_square_matrix(matrix):
    """Raise a descriptive error unless `matrix` is a list of equal-length rows."""
    if not isinstance(matrix, list):
        raise TypeError("matrix must be a list of lists")
    size = len(matrix)
    for index, row in enumerate(matrix):
        if not isinstance(row, list):
            raise TypeError("row {} is not a list".format(index))
        if len(row) != size:
            raise ValueError(
                "row {} has {} entries, expected {}".format(index, len(row), size)
            )
    return size


def rotate_matrix_90_clockwise(matrix):
    """Rotate a square matrix 90 degrees clockwise in place and return it."""
    size = validate_square_matrix(matrix)
    for layer in range(size // 2):
        last = size - 1 - layer
        for offset in range(layer, last):
            shift = offset - layer
            top = matrix[layer][offset]
            matrix[layer][offset] = matrix[last - shift][layer]
            matrix[last - shift][layer] = matrix[last][last - shift]
            matrix[last][last - shift] = matrix[offset][last]
            matrix[offset][last] = top
    return matrix


def rotate_matrix_times(matrix, quarter_turns):
    """Apply the clockwise quarter rotation `quarter_turns` times (may be negative)."""
    turns = quarter_turns % 4
    for _ in range(turns):
        rotate_matrix_90_clockwise(matrix)
    return matrix


def format_matrix(matrix):
    """Render a matrix as right-aligned rows sharing a single column width."""
    width = 1
    for row in matrix:
        for value in row:
            text = str(value)
            if len(text) > width:
                width = len(text)
    lines = []
    for row in matrix:
        cells = [str(value).rjust(width) for value in row]
        lines.append(" ".join(cells))
    return "\n".join(lines)


def report_rotations(matrix, max_turns=4):
    """Print the matrix after each successive quarter turn, starting from zero turns."""
    working = [list(row) for row in matrix]
    for turns in range(max_turns + 1):
        print("after {} quarter turn(s):".format(turns))
        print(format_matrix(working))
        if turns < max_turns:
            rotate_matrix_90_clockwise(working)
    return working


def main():
    samples = [
        [[1, 2], [3, 4]],
        [[1, 2, 3], [4, 5, 6], [7, 8, 9]],
    ]
