def count_set_bits(n):
    """Return the number of '1' bits in the binary representation of n."""
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("count_set_bits expects a non-negative integer")
    if n < 0:
        raise ValueError("count_set_bits expects a non-negative integer")
    count = 0
    while n:
        n &= n - 1
        count += 1
    return count


def parse_argument(text):
    """Convert a command-line token into a non-negative integer."""
    token = text.strip().lower()
    if token.startswith("0b"):
        base = 2
    elif token.startswith("0x"):
        base = 16
    else:
        base = 10
    try:
        value = int(token, base)
    except ValueError:
        raise ValueError("not a valid integer: %s" % text)
    if value < 0:
        raise ValueError("negative values are not supported: %s" % text)
    return value


def describe(n):
    """Build a one-line report about the set bits of n."""
    bits = count_set_bits(n)
    positions = []
    index = 0
    remaining = n
    while remaining:
        if remaining & 1:
            positions.append(index)
        remaining >>= 1
        index += 1
    if positions:
        where = ", ".join(str(p) for p in positions)
    else:
        where = "none"
    return "{0} = 0b{1} -> {2} set bit(s) at position(s): {3}".format(
        n, format(n, "b"), bits, where
    )


def main(argv):
    if len(argv) > 1:
        tokens = argv[1:]
    else:
        tokens = ["5", "10", "0", "255", "0b1011", "0xff"]
    exit_code = 0
    for token in tokens:
        try:
            value = parse_argument(token)
        except ValueError as err:
            print("error: %s" % err)
            exit_code = 1
            continue
        print(describe(value))
    return exit_code


if __name__ == "__main__":
