def validate_inventory(inventory):
    """Return a cleaned copy of the inventory, rejecting malformed entries."""
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dict of item_name: stock_level")
    cleaned = {}
    for name, level in inventory.items():
        if not isinstance(name, str):
            raise TypeError("item names must be strings, got %r" % (name,))
        if isinstance(level, bool) or not isinstance(level, int):
            raise TypeError("stock level for %s must be an int" % name)
        if level < 0:
            raise ValueError("stock level for %s cannot be negative" % name)
        cleaned[name.strip()] = level
    return cleaned


def get_restock_reminders(inventory, threshold):
    """Return alphabetically sorted names of items stocked below threshold."""
    items = validate_inventory(inventory)
    if isinstance(threshold, bool) or not isinstance(threshold, int):
        raise TypeError("threshold must be an int")
    reminders = []
    for name, level in items.items():
        if level < threshold:
            reminders.append(name)
    return sorted(reminders)


def shortfalls(inventory, threshold):
    """Map each item needing restocking to the number of units still required."""
    items = validate_inventory(inventory)
    result = {}
    for name in get_restock_reminders(items, threshold):
        result[name] = threshold - items[name]
    return result


def format_report(inventory, threshold):
    """Build a human-readable restock report as a list of text lines."""
    gaps = shortfalls(inventory, threshold)
    lines = ["Restock report (threshold: %d)" % threshold]
    if not gaps:
        lines.append("  All items are sufficiently stocked.")
        return lines
    width = max(len(name) for name in gaps)
    for name in sorted(gaps):
        missing = gaps[name]
        unit = "unit" if missing == 1 else "units"
        lines.append("  %-*s  order %d %s" % (width, name, missing, unit))
    lines.append("  Items to reorder: %d" % len(gaps))
    return lines


def main():
    catalogues = [
        ({'apple': 5, 'banana': 12, 'orange': 3}, 5),
        ({'milk': 1, 'bread': 0, 'eggs': 2}, 3),
        ({'rice': 40, 'beans': 25}, 10),
    ]
    for inventory, threshold in catalogues:
        for line in format_report(inventory, threshold):
            print(line)
        print()

    bad_inventories = [
        ({'flour': -2}, 5),
        ({'sugar': "many"}, 5),
    ]
    for inventory, threshold in bad_inventories:
        try:
            get_restock_reminders(inventory, threshold)
        except (TypeError, ValueError) as exc:
            print("Rejected %r: %s" % (inventory, exc))


if __name__ == "__main__":
    main()

