def count_occurrences(items):
    """Return a dict mapping each element of *items* to its number of occurrences."""
    counts = {}
    for item in items:
        if item in counts:
            counts[item] += 1
        else:
            counts[item] = 1
    return counts


def find_most_frequent_element(items):
    """Return the element occurring most often in *items*, or None if empty."""
    best = None
    best_count = 0
    for item, count in count_occurrences(items).items():
        if count > best_count:
            best = item
            best_count = count
    return best


def tied_elements(items):
    """Return every element that reaches the maximum frequency, in first-seen order."""
    counts = count_occurrences(items)
    if not counts:
        return []
    top = max(counts.values())
    winners = []
    for item in items:
        if counts[item] == top and item not in winners:
            winners.append(item)
    return winners


def format_report(items):
    """Build a human readable summary of the frequencies in *items*."""
    counts = count_occurrences(items)
    if not counts:
        return "empty list: no most frequent element"
    lines = []
    ordered = sorted(counts.items(), key=lambda pair: (-pair[1], repr(pair[0])))
    for item, count in ordered:
        plural = "s" if count != 1 else ""
        lines.append("  {!r}: {} occurrence{}".format(item, count, plural))
    winners = tied_elements(items)
    if len(winners) > 1:
        names = ", ".join(repr(w) for w in winners)
        lines.append("  tie between {} -> picking {!r}".format(names, find_most_frequent_element(items)))
    else:
        lines.append("  winner: {!r}".format(winners[0]))
    return "\n".join(lines)


def main():
    datasets = [
        [1, 3, 2, 1, 3, 1],
        ['a', 'b', 'b', 'c', 'a'],
        [],
        [7],
        [True, False, False, None, None],
    ]
    for data in datasets:
        print("input: {!r}".format(data))
        print(format_report(data))
        winner = find_most_frequent_element(data)
        if winner is None:
            print("result: None")
        else:
            print("result: {!r}".format(winner))
        print()


if __name__ == "__main__":
    main()

