def contains_sublist(main_list, sub_list):
    """Return True if sub_list appears contiguously inside main_list."""
    if not isinstance(main_list, list) or not isinstance(sub_list, list):
        raise TypeError("both arguments must be lists")
    return find_sublist_index(main_list, sub_list) != -1


def find_sublist_index(main_list, sub_list):
    """Return the index of the first contiguous match, or -1 if absent."""
    n = len(main_list)
    m = len(sub_list)
    if m == 0:
        return 0
    for start in range(n - m + 1):
        offset = 0
        while offset < m and main_list[start + offset] == sub_list[offset]:
            offset += 1
        if offset == m:
            return start
    return -1


def count_sublist_occurrences(main_list, sub_list):
    """Count non-overlapping occurrences of sub_list within main_list."""
    if len(sub_list) == 0:
        return 0
    total = 0
    position = 0
    while position <= len(main_list) - len(sub_list):
        window = main_list[position:position + len(sub_list)]
        if window == sub_list:
            total += 1
            position += len(sub_list)
        else:
            position += 1
    return total


def describe(main_list, sub_list):
    """Build a one-line human readable report about a single query."""
    found = contains_sublist(main_list, sub_list)
    parts = ["{} in {} -> {}".format(sub_list, main_list, found)]
    if found:
        index = find_sublist_index(main_list, sub_list)
        parts.append("first index {}".format(index))
        occurrences = count_sublist_occurrences(main_list, sub_list)
        if occurrences > 1:
            parts.append("{} occurrences".format(occurrences))
    return ", ".join(parts)


def main():
    queries = [
        ([1, 2, 3, 4, 5], [2, 3]),
        ([1, 2, 3, 4, 5], [1, 3]),
        ([1, 2, 3, 4, 5], []),
        ([], [7]),
        ([1, 2, 1, 2, 1, 2], [1, 2]),
        (["a", "b", "c"], ["b", "c"]),
    ]
    matches = 0
    for main_list, sub_list in queries:
        print(describe(main_list, sub_list))
        if contains_sublist(main_list, sub_list):
            matches += 1
    print("{} of {} queries matched".format(matches, len(queries)))


if __name__ == "__main__":
    main()

