def merge_dicts(d1, d2):
    """Return a new dict with d1's entries overridden by d2's."""
    for name, candidate in (("d1", d1), ("d2", d2)):
        if not isinstance(candidate, dict):
            raise TypeError("%s must be a dict, got %s" % (name, type(candidate).__name__))
    merged = {}
    for key, value in d1.items():
        merged[key] = value
    for key, value in d2.items():
        merged[key] = value
    return merged


def merge_all(dicts):
    """Fold merge_dicts over a sequence; later dicts win."""
    result = {}
    for item in dicts:
        result = merge_dicts(result, item)
    return result


def deep_merge(d1, d2):
    """Like merge_dicts, but nested dicts are merged instead of replaced."""
    merged = merge_dicts(d1, d2)
    for key, value in d2.items():
        left = d1.get(key)
        if isinstance(left, dict) and isinstance(value, dict):
            merged[key] = deep_merge(left, value)
    return merged


def overridden_keys(d1, d2):
    """Keys present in both dicts where d2 actually changes the value."""
    changed = []
    for key in d1:
        if key in d2 and d1[key] != d2[key]:
            changed.append(key)
    return sorted(changed, key=repr)


def format_dict(d):
    """Render a dict with keys in sorted order for stable output."""
    parts = []
    for key in sorted(d, key=repr):
        parts.append("%r: %r" % (key, d[key]))
    return "{" + ", ".join(parts) + "}"


def report(label, d1, d2, merged):
    lines = ["%s: %s + %s -> %s" % (label, format_dict(d1), format_dict(d2), format_dict(merged))]
    changed = overridden_keys(d1, d2)
    if changed:
        for key in changed:
            lines.append("    %r: %r overridden by %r" % (key, d1[key], d2[key]))
    else:
        lines.append("    no values overridden")
    return "\n".join(lines)


def main():
    pairs = [
        ("example 1", {'a': 1, 'b': 2}, {'b': 3, 'c': 4}),
        ("example 2", {'x': 10}, {'y': 20}),
    ]
    for label, first, second in pairs:
        print(report(label, first, second, merge_dicts(first, second)))

    defaults = {'host': 'localhost', 'port': 80, 'flags': {'debug': False, 'trace': False}}
    user = {'port': 8080, 'flags': {'debug': True}}
    print("shallow config:", format_dict(merge_dicts(defaults, user)))
    print("deep config:   ", format_dict(deep_merge(defaults, user)))

    layers = [defaults, user, {'host': 'example.com'}]
    print("all layers:    ", format_dict(merge_all(layers)))


if __name__ == "__main__":
    main()

