def is_balanced(s: str) -> bool:
    stack = []
    mapping = {")": "(", "}": "{", "]": "["}

    for char in s:
        if char in mapping.values():
            stack.append(char)
        elif char in mapping:
            if not stack:
                return False
            top_element = stack.pop()
            if mapping[char] != top_element:
                return False
        else:
            # Should not happen given the problem description, but good practice
            pass # Or raise an error if unexpected characters are possible

    return not stack

