def find_common_elements(list1, list2):
    try:
        set1 = set(list1)
        common_elements = []
        for item in list2:
            if item in set1:
                common_elements.append(item)
        if not common_elements:
            return []
        else:
            final_set = set()
            for element in common_elements:
                final_set.add(element)
            return list(final_set)
    except TypeError:
        print("Error: Input lists must contain hashable elements.")
        return []

