VOWELS = "aeiou"


def count_vowels_consonants(text):
    """Return (vowel_count, consonant_count) for the alphabetic characters of text."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    vowels = 0
    consonants = 0
    for char in text:
        if not char.isalpha():
            continue
        if char.lower() in VOWELS:
            vowels += 1
        else:
            consonants += 1
    return vowels, consonants


def letter_ratio(text):
    """Return the share of alphabetic characters that are vowels, or None if none."""
    vowels, consonants = count_vowels_consonants(text)
    total = vowels + consonants
    if total == 0:
        return None
    return vowels / total


def describe(text):
    """Build a one-line human readable report for a single input string."""
    vowels, consonants = count_vowels_consonants(text)
    ratio = letter_ratio(text)
    if ratio is None:
        summary = "no letters"
    else:
        summary = "{:.0%} vowels".format(ratio)
    return "{!r}: ({}, {}) - {}".format(text, vowels, consonants, summary)


def most_vowel_heavy(samples):
    """Return the sample with the highest vowel share, ignoring letterless samples."""
    best = None
    best_ratio = -1.0
    for sample in samples:
        ratio = letter_ratio(sample)
        if ratio is None:
            continue
        if ratio > best_ratio:
            best = sample
            best_ratio = ratio
    return best


def totals(samples):
    """Sum the vowel and consonant counts across many samples."""
    vowels = 0
    consonants = 0
    for sample in samples:
        v, c = count_vowels_consonants(sample)
        vowels += v
        consonants += c
    return vowels, consonants


def main():
    samples = ["Hello World", "Python123", "1234!", "Aeiou", "rhythm"]
    for sample in samples:
        print(describe(sample))
    winner = most_vowel_heavy(samples)
    if winner is None:
        print("No sample contained letters.")
    else:
        print("Most vowel heavy: {!r}".format(winner))
    vowels, consonants = totals(samples)
    print("Overall: {} vowels, {} consonants".format(vowels, consonants))


if __name__ == "__main__":
    main()

