class SimpleQueue:
    """A first-in, first-out queue backed by a plain Python list."""

    def __init__(self, items=None):
        self._items = []
        if items is not None:
            for item in items:
                self.enqueue(item)

    def enqueue(self, item):
        self._items.append(item)

    def dequeue(self):
        if not self._items:
            raise IndexError("dequeue from an empty queue")
        return self._items.pop(0)

    def peek(self):
        if not self._items:
            raise IndexError("peek at an empty queue")
        return self._items[0]

    def __len__(self):
        return len(self._items)

    def __repr__(self):
        return "SimpleQueue({!r})".format(self._items)


def parse_script(text):
    """Turn a newline-separated script into a list of (op, argument) pairs."""
    commands = []
    for lineno, raw in enumerate(text.splitlines(), start=1):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        parts = line.split(None, 1)
        op = parts[0].lower()
        if op == "enqueue":
            if len(parts) != 2:
                raise ValueError("line {}: enqueue needs a value".format(lineno))
            commands.append((op, parts[1]))
        elif op in ("dequeue", "peek"):
            commands.append((op, None))
        else:
            raise ValueError("line {}: unknown command {!r}".format(lineno, op))
    return commands


def run_script(text):
    """Execute a queue script and return a report of every produced value."""
    queue = SimpleQueue()
    report = []
    for op, argument in parse_script(text):
        if op == "enqueue":
            queue.enqueue(argument)
            report.append("enqueued {} (size {})".format(argument, len(queue)))
        else:
            try:
                value = queue.peek() if op == "peek" else queue.dequeue()
            except IndexError as error:
                report.append("{} failed: {}".format(op, error))
            else:
                report.append("{} -> {}".format(op, value))
    return report


def main():
    script = "\n".join([
        "# warm up the queue",
        "enqueue 1",
        "enqueue 2",
        "dequeue",
        "peek",
        "dequeue",
        "dequeue",
    ])
    for line in run_script(script):
        print(line)


if __name__ == "__main__":
    main()

