DIGITS = "0123456789"


def is_all_digits(s):
    """Return True if s is non-empty and made up only of decimal digits."""
    if not isinstance(s, str):
        raise TypeError("is_all_digits expects a string")
    if s == "":
        return False
    for ch in s:
        if ch not in DIGITS:
            return False
    return True


def split_fields(line):
    """Split a comma-separated record into trimmed field values."""
    fields = []
    for part in line.split(","):
        fields.append(part.strip())
    return fields


def classify_fields(fields):
    """Pair each field with a label describing whether it is purely numeric."""
    classified = []
    for field in fields:
        if is_all_digits(field):
            classified.append((field, "numeric"))
        else:
            classified.append((field, "text"))
    return classified


def numeric_values(fields):
    """Convert every all-digit field to an int, ignoring the rest."""
    values = []
    for field in fields:
        if is_all_digits(field):
            values.append(int(field))
    return values


def format_report(line):
    """Build a human readable report for one comma-separated record."""
    fields = split_fields(line)
    lines = ["record: " + line]
    for field, kind in classify_fields(fields):
        shown = field if field else "<empty>"
        lines.append("  {:<10} -> {}".format(shown, kind))
    values = numeric_values(fields)
    if values:
        lines.append("  sum of numeric fields: {}".format(sum(values)))
    else:
        lines.append("  no numeric fields found")
    return "\n".join(lines)


def main():
    samples = [
        "12345",
        "123a45",
        "7,42,alpha, 99 ,",
        "id,0007,-5,00",
