import re
import sys

TOKEN_PATTERN = re.compile(r"[a-z0-9]+(?:'[a-z]+)*")


def normalize(text):
    """Lower-case the text and replace punctuation with spaces."""
    if not isinstance(text, str):
        raise TypeError('text must be a string, got %s' % type(text).__name__)
    cleaned = []
    for char in text.lower():
        if char.isalnum() or char == "'":
            cleaned.append(char)
        else:
            cleaned.append(' ')
    return ''.join(cleaned)


def tokenize(text):
    """Split normalized text into words, discarding stray apostrophes."""
    words = []
    for match in TOKEN_PATTERN.finditer(normalize(text)):
        words.append(match.group(0))
    return words


def word_counts(text):
    """Count occurrences of each word in text, ignoring case and punctuation."""
    counts = {}
    for word in tokenize(text):
        if word in counts:
            counts[word] += 1
        else:
            counts[word] = 1
    return counts


def rank(counts):
    """Order words by descending frequency, then alphabetically."""
    return sorted(counts.items(), key=lambda item: (-item[1], item[0]))


def format_report(counts, limit=None):
    """Build an aligned text table of the most frequent words."""
    entries = rank(counts)
    if limit is not None:
        entries = entries[:limit]
    if not entries:
        return 'no words found'
    width = max(len(word) for word, count in entries)
    total = sum(counts.values())
    lines = []
    for word, count in entries:
        share = 100.0 * count / total
        lines.append('%-*s %5d %6.1f%%' % (width, word, count, share))
    lines.append('%-*s %5d %6.1f%%' % (width, 'TOTAL', total, 100.0))
    return '\n'.join(lines)


def main(argv):
    if len(argv) > 1:
        text = ' '.join(argv[1:])
    else:
        text = sys.stdin.read()
    print(format_report(word_counts(text), limit=20))
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))

