class SimpleStack:
    """A last-in, first-out container backed by a plain Python list."""

    def __init__(self):
        self._items = []

    def push(self, item):
        self._items.append(item)

    def pop(self):
        if not self._items:
            raise IndexError("pop from an empty SimpleStack")
        return self._items.pop()

    def __len__(self):
        return len(self._items)


def evaluate_rpn(expression):
    """Evaluate a reverse-polish expression such as '3 4 + 2 *'."""
    operations = {
        "+": lambda a, b: a + b,
        "-": lambda a, b: a - b,
        "*": lambda a, b: a * b,
        "/": lambda a, b: a / b,
    }
    stack = SimpleStack()
    for token in expression.split():
        if token in operations:
            try:
                right = stack.pop()
                left = stack.pop()
            except IndexError:
                raise ValueError("not enough operands for '{}'".format(token))
            if token == "/" and right == 0:
                raise ValueError("division by zero in expression")
            stack.push(operations[token](left, right))
        else:
            try:
                stack.push(float(token))
            except ValueError:
                raise ValueError("unrecognised token: {!r}".format(token))
    if len(stack) != 1:
        raise ValueError("malformed expression: {!r}".format(expression))
    return stack.pop()


def report(expressions):
    """Return one formatted result line per expression."""
    lines = []
    for expression in expressions:
        try:
            value = evaluate_rpn(expression)
        except ValueError as error:
            lines.append("{:<16} -> error: {}".format(expression, error))
        else:
            lines.append("{:<16} -> {:g}".format(expression, value))
    return lines


def main():
    stack = SimpleStack()
    stack.push(1)
    stack.push(2)
    print("popped:", stack.pop())
    print("popped:", stack.pop())
    try:
        stack.pop()
    except IndexError as error:
        print("empty stack:", error)
    for line in report(["3 4 +", "5 1 2 + 4 * -", "2 0 /", "1 2"]):
        print(line)


if __name__ == "__main__":
    main()

