import random


def validate_input(nums, k):
    if not isinstance(nums, (list, tuple)):
        raise TypeError("nums must be a list or tuple of numbers")
    if len(nums) == 0:
        raise ValueError("nums must not be empty")
    for value in nums:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("nums must contain only numbers")
    if not isinstance(k, int) or isinstance(k, bool):
        raise TypeError("k must be an integer")
    if k < 1 or k > len(nums):
        raise ValueError("k must satisfy 1 <= k <= len(nums)")


def partition(values, left, right, pivot_index):
    pivot = values[pivot_index]
    values[pivot_index], values[right] = values[right], values[pivot_index]
    store = left
    for i in range(left, right):
        if values[i] > pivot:
            values[i], values[store] = values[store], values[i]
            store += 1
    values[store], values[right] = values[right], values[store]
    return store


def quickselect(values, left, right, target):
    while True:
        if left == right:
            return values[left]
        pivot_index = random.randint(left, right)
        pivot_index = partition(values, left, right, pivot_index)
        if target == pivot_index:
            return values[target]
        elif target < pivot_index:
            right = pivot_index - 1
        else:
            left = pivot_index + 1


def find_kth_largest(nums, k):
    validate_input(nums, k)
    values = list(nums)
    return quickselect(values, 0, len(values) - 1, k - 1)


def describe(nums, k):
    result = find_kth_largest(nums, k)
    distinct = len(set(nums))
    suffix = "th"
    if k % 100 not in (11, 12, 13):
        suffix = {1: "st", 2: "nd", 3: "rd"}.get(k % 10, "th")
    return "{}{} largest of {} ({} distinct) is {}".format(
        k, suffix, nums, distinct, result)


def main():
    cases = [
