def digit_square_sum(n):
    total = 0
    while n > 0:
        n, digit = divmod(n, 10)
        total += digit * digit
    return total


def is_happy_number(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 1:
        raise ValueError("n must be a positive integer")
    seen = set()
    while n != 1 and n not in seen:
        seen.add(n)
        n = digit_square_sum(n)
    return n == 1


def happy_sequence(n):
    steps = [n]
    seen = {n}
    while steps[-1] != 1:
        nxt = digit_square_sum(steps[-1])
        if nxt in seen:
            steps.append(nxt)
            break
        seen.add(nxt)
        steps.append(nxt)
    return steps


def happy_numbers_up_to(limit):
    result = []
    for candidate in range(1, limit + 1):
        if is_happy_number(candidate):
            result.append(candidate)
    return result


def format_report(n):
    chain = happy_sequence(n)
    arrow = " -> ".join(str(value) for value in chain)
    if chain[-1] == 1:
        verdict = "happy"
    else:
        verdict = "unhappy (cycle detected)"
    return "{0}: {1} [{2}]".format(n, arrow, verdict)


def main():
    for number in (19, 4, 7, 23, 100):
        print(format_report(number))
    limit = 50
    happy = happy_numbers_up_to(limit)
    print("Happy numbers up to {0}: {1}".format(limit, happy))
    print("Count: {0}".format(len(happy)))
    for bad_input in (0, -5, 2.5):
        try:
            is_happy_number(bad_input)
        except (TypeError, ValueError) as error:
            print("Rejected {0!r}: {1}".format(bad_input, error))


if __name__ == "__main__":
    main()

