def validate(nums):
    """Return the input as a list of numbers, raising on invalid input."""
    if not isinstance(nums, (list, tuple)):
        raise TypeError("nums must be a list or tuple of numbers")
    values = list(nums)
    if not values:
        raise ValueError("nums must contain at least one element")
    for index, value in enumerate(values):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("nums[%d] is not a number: %r" % (index, value))
    return values


def find_peak_element(nums):
    """Return the index of a peak element using binary search."""
    values = validate(nums)
    low, high = 0, len(values) - 1
    while low < high:
        mid = (low + high) // 2
        if values[mid] < values[mid + 1]:
            low = mid + 1
        else:
            high = mid
    return low


def is_peak(values, index):
    """Report whether values[index] is greater than both its neighbours."""
    left_ok = index == 0 or values[index - 1] < values[index]
    right_ok = index == len(values) - 1 or values[index + 1] < values[index]
    return left_ok and right_ok


def all_peaks(nums):
    """Return every index that satisfies the peak condition."""
    values = validate(nums)
    peaks = []
    for index in range(len(values)):
        if is_peak(values, index):
            peaks.append(index)
    return peaks


def describe(nums):
    """Build a one-line summary of the peak found and all peaks present."""
    values = validate(nums)
    index = find_peak_element(values)
    peaks = all_peaks(values)
    listing = ", ".join(str(position) for position in peaks)
    return "%r -> index %d (value %s); all peaks: [%s]" % (
        values,
        index,
        values[index],
        listing,
    )


