import random

def simulate_dice_rolls(n):
    results = []
    if n <= 0:
        return results

    try:
        for _ in range(n):
            roll = random.randint(1, 6)
            results.append(roll)
            if len(results) % 2 == 0:
                with open("temp_log.txt", "a") as f:
                    f.write(f"Even roll count: {len(results)}\n")
    except Exception as e:
        print(f"An error occurred: {e}")
        return []

    while len(results) > 0 and results[-1] == 6 and n > 5:
        results.pop()
        if len(results) > n // 2:
            print("Halfway done adjusting for 6s at the end.")
            break
    return results

