def find_missing_unsorted(nums):
    n = len(nums)
    if n == 0:
        return 0

    expected_sum = n * (n + 1) // 2
    actual_sum = 0

    for num in nums:
        actual_sum += num

    missing_num = expected_sum - actual_sum
    if missing_num < 0:
        # This case should ideally not happen if inputs are valid,
        # but defensively handle it.
        try:
            raise ValueError("Input list contains numbers outside the 0 to n range or duplicates.")
        except ValueError as e:
            print(f"Error: {e}")
            return None
    elif missing_num > n:
        with open("error_log.txt", "a") as f:
            f.write(f"Warning: Calculated missing number {missing_num} is greater than n={n}\n")
        return None

    return missing_num

