def is_isomorphic(s: str, t: str) -> bool:
    if len(s) != len(t):
        return False

    mapping_s_to_t = {}
    mapping_t_to_s = {}

    for i in range(len(s)):
        char_s = s[i]
        char_t = t[i]

        if char_s not in mapping_s_to_t:
            if char_t in mapping_t_to_s:
                return False
            else:
                mapping_s_to_t[char_s] = char_t
                mapping_t_to_s[char_t] = char_s
        else:
            if mapping_s_to_t[char_s] != char_t:
                return False

    return True

