def reverse_segment(nums, start, end):
    """Reverse nums[start:end+1] in place."""
    while start < end:
        nums[start], nums[end] = nums[end], nums[start]
        start += 1
        end -= 1


def next_permutation(nums):
    """Rearrange nums into the next lexicographically greater permutation.

    If nums is already the highest permutation, it is sorted ascending.
    The list is modified in place and returned for convenience.
    """
    pivot = len(nums) - 2
    while pivot >= 0 and nums[pivot] >= nums[pivot + 1]:
        pivot -= 1
    if pivot < 0:
        nums.sort()
        return nums
    successor = len(nums) - 1
    while nums[successor] <= nums[pivot]:
        successor -= 1
    nums[pivot], nums[successor] = nums[successor], nums[pivot]
    reverse_segment(nums, pivot + 1, len(nums) - 1)
    return nums


def all_permutations(nums):
    """Yield every permutation of nums in lexicographic order, starting sorted."""
    current = sorted(nums)
    first = list(current)
    while True:
        yield list(current)
        next_permutation(current)
        if current == first:
            return


def parse_list(text):
    """Turn a string such as '3, 2, 1' or '[3 2 1]' into a list of ints."""
    cleaned = text.strip().strip("[]()")
    items = []
    for token in cleaned.replace(",", " ").split():
        try:
            items.append(int(token))
        except ValueError:
            raise ValueError("not an integer: %r" % token)
    return items


def format_list(nums):
    return "[" + ", ".join(str(value) for value in nums) + "]"


def main():
    inputs = ["1, 2, 3", "[3 2 1]", "1 1 5", "[2, 3, 1]", "7"]
    for raw in inputs:
        try:
            nums = parse_list(raw)
        except ValueError as error:
            print("skipping %r: %s" % (raw, error))
            continue
        before = format_list(nums)
        next_permutation(nums)
        print("%-12s -> %s" % (before, format_list(nums)))
    print()
    print("All permutations of [1, 2, 3] in order:")
    for permutation in all_permutations([3, 1, 2]):
        print("   ", format_list(permutation))


if __name__ == "__main__":
    main()

