def find_largest(numbers: list[int | float]) -> int | float:
    """Return the largest value in a non-empty list of numbers."""
    largest = numbers[0]
    for value in numbers[1:]:
        if value > largest:
            largest = value
    return largest


def parse_numbers(text: str) -> list[int | float]:
    """Turn a comma or whitespace separated string into a list of numbers."""
    tokens = text.replace(",", " ").split()
    numbers: list[int | float] = []
    for token in tokens:
        try:
            numbers.append(int(token))
        except ValueError:
            numbers.append(float(token))
    return numbers


def index_of_largest(numbers: list[int | float]) -> int:
    """Return the position of the first occurrence of the largest value."""
    target = find_largest(numbers)
    for position, value in enumerate(numbers):
        if value == target:
            return position
    return -1


def format_number(value: int | float) -> str:
    """Render a number without a trailing '.0' for whole floats."""
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)


def describe(text: str) -> str:
    """Build a one-line report about the largest number in a data line."""
    numbers = parse_numbers(text)
    if not numbers:
        return f"{text!r}: no numbers found"
    largest = find_largest(numbers)
    position = index_of_largest(numbers)
    rendered = ", ".join(format_number(value) for value in numbers)
    return (
        f"[{rendered}] -> largest {format_number(largest)}"
        f" at index {position} of {len(numbers)}"
    )


def main() -> None:
    lines = [
        "3, 1, 4, 1, 5, 9, 2",
        "-5 -1 -10",
        "2.5, 2.50, 1",
        "42",
        "",
    ]
    for line in lines:
        print(describe(line))


if __name__ == "__main__":
    main()

