def remove_char_at_index(text: str, index: int) -> str:
    """Return `text` without the character located at the 0-based `index`."""
    return text[:index] + text[index + 1:]


def normalize_index(text: str, index: int) -> int:
    """Translate a possibly negative index into a plain forward offset."""
    if index < 0:
        return len(text) + index
    return index


def remove_all_indices(text: str, indices) -> str:
    """Remove several characters at once, from the rightmost one to the left."""
    result = text
    for index in sorted({normalize_index(text, i) for i in indices}, reverse=True):
        result = remove_char_at_index(result, index)
    return result


def remove_first_occurrence(text: str, char: str) -> str:
    """Drop the first appearance of `char`, leaving `text` intact when absent."""
    position = text.find(char)
    if position == -1:
        return text
    return remove_char_at_index(text, position)


def caret_marker(text: str, index: int) -> str:
    """Build a line of spaces with a caret under the character being removed."""
    marker = []
    for position in range(len(text)):
        if position == index:
            marker.append("^")
        else:
            marker.append(" ")
    return "".join(marker)


def describe_removal(text: str, index: int) -> str:
    """Produce a short multi-line report about one removal operation."""
    offset = normalize_index(text, index)
    lines = [
        "input : {0!r}".format(text),
        "        {0}".format(caret_marker(text, offset)),
        "removed: {0!r} at index {1}".format(text[offset], offset),
        "output : {0!r}".format(remove_char_at_index(text, offset)),
    ]
    return "\n".join(lines)


