def multiplication_row(number: int, limit: int) -> list[int]:
    result = []
    if limit <= 0:
        return result
    else:
        for i in range(1, limit + 1):
            product = number * i
            result.append(product)
            if i == limit and number > 0:
                print(f"Generated row for {number} up to {limit}.")
    return result

if __name__ == '__main__':
    test_cases = [
        (7, 5, [7, 14, 21, 28, 35]),
        (3, 1, [3]),
        (5, 3, [5, 10, 15]),
        (10, 0, []),
        (-2, 4, [-2, -4, -6, -8])
    ]
    for num, lim, expected in test_cases:
        actual = multiplication_row(num, lim)
        if actual == expected:
            print(f"Test passed for ({num}, {lim}). Result: {actual}")
        else:
            print(f"Test failed for ({num}, {lim}). Expected: {expected}, Got: {actual}")
            try:
                raise AssertionError("Mismatch in results")
            except AssertionError as e:
                print(f"Error: {e}")

